apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata: { name: api-ingress, namespace: shop }
spec:
  podSelector: { matchLabels: { app.kubernetes.io/name: api } }
  policyTypes: [Ingress]
  ingress:
    - from:
        - podSelector: { matchLabels: { app.kubernetes.io/name: web } }
      ports: [{ protocol: TCP, port: 8080 }]

env:
  - name: LOG_LEVEL
    valueFrom: { configMapKeyRef: { name: api-config, key: log-level } }
volumeMounts:
  - { name: credentials, mountPath: /var/run/secrets/app, readOnly: true }
volumes:
  - name: credentials
    secret: { secretName: api-credentials, defaultMode: 0400 }

startupProbe: { httpGet: { path: /health/startup, port: http }, failureThreshold: 30, periodSeconds: 2 }
readinessProbe: { httpGet: { path: /health/ready, port: http }, periodSeconds: 5, timeoutSeconds: 2 }
livenessProbe: { httpGet: { path: /health/live, port: http }, periodSeconds: 10, timeoutSeconds: 2, failureThreshold: 3 }

resources:
  requests: { cpu: 250m, memory: 256Mi, ephemeral-storage: 256Mi }
  limits: { cpu: "1", memory: 512Mi, ephemeral-storage: 1Gi }
